      SUBROUTINE RDINT(IVAL,FLAG)C---- DECODE UNSIGNED INTEGERC-------------------------------------------------------------------      LOGICAL         FLAGC-------------------------------------------------------------------      INCLUDE 'IODATA.CIN'      INCLUDE 'IOFLAG.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'RDBUFF.CIN'      INCLUDE 'RDCHAR.CIN'C-------------------------------------------------------------------      CHARACTER*10    NUMREP      INTEGER         ICOLB, IDIG, ISTARTC-------------------------------------------------------------------      FLAG = .TRUE.      IVAL = 0      NUMREP = BLANK      ICOLB = ICOL   10 IDIG = INDEX('0123456789',ITEM) - 1      IF (IDIG .GE. 0) THEN        FLAG = .FALSE.        CALL RDFWRD        GO TO 10      ELSE        CALL RDBACK        ISTART = ICOLB + 10 - ICOL        NUMREP(ISTART:10) = KTEXT(ICOLB:ICOL)        READ (NUMREP,930) IVAL      ENDIF      IF (FLAG) THEN        CALL RDFAIL        WRITE (NOUT,910)      ELSE IF (INDEX('.DE',ITEM) .NE. 0) THEN        CALL RDSKIP('0123456789.E')        IF (ENDFIL) GO TO 20        CALL RDFAIL        WRITE (NOUT,920)        FLAG = .TRUE.        IVAL = 0      ENDIF   20 CONTINUE      RETURNC-------------------------------------------------------------------  910 FORMAT(' *** ERROR *** UNSIGNED INTEGER EXPECTED'/' ')  920 FORMAT(' *** ERROR *** REAL VALUE NOT PERMITTED'/' ')  930 FORMAT (I10)C-------------------------------------------------------------------      END